get_ecommerce_settings.code:
var response = await client.EcommerceSettings.GetEcommerceSettingsAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var ecommerceSettings = (IReadOnlyDictionary<string, object?>)body["ecommerce_settings"]!;
var continueShopping = (IReadOnlyDictionary<string, object?>)ecommerceSettings["continue_shopping"]!;
Console.WriteLine($"{continueShopping["enable_continue_shopping"]} {continueShopping["continue_shopping_target"]}");

patch_ecommerce_settings.code:
var response = await client.EcommerceSettings.PatchEcommerceSettingsAsync(new Dictionary<string, object?>
{
    ["ecommerce_settings"] = new Dictionary<string, object?>
    {
        ["continue_shopping"] = new Dictionary<string, object?> { ["continue_shopping_target"] = "previous" },
        ["order_filters"] = new Dictionary<string, object?> { ["default_payment_status"] = "unpaid" },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var ecommerceSettings = (IReadOnlyDictionary<string, object?>)body["ecommerce_settings"]!;
var continueShopping = (IReadOnlyDictionary<string, object?>)ecommerceSettings["continue_shopping"]!;
Console.WriteLine(continueShopping["continue_shopping_target"]);

